/**
 * The footprint preview must show footprints exactly where kbplacer (the PCB
 * generator backend) places them. pcb-golden-pads.json holds pad centres of a
 * switch and diode placed by kbplacer with KiCad, generated by
 * scripts/generate-pcb-golden-pads.py.
 */
import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, it, expect } from 'vitest'
import {
  applyDiodeTransform,
  applySwitchTransform,
  offsetSvgTransform,
  parseViewBox,
  switchLocalToBoard,
  switchLocalSvgTransform,
  switchSvgTransform,
  type BoardSide,
} from '../footprintUtils'
import { placePoint } from '@/utils/kicad/transform'
import golden from './fixtures/pcb-golden-pads.json'

type Point = { x: number; y: number }

interface GoldenPad {
  number: string
  switch_local: { x_nm: number; y_nm: number }
  board: { x_nm: number; y_nm: number }
}
interface GoldenCase {
  switch_footprint: string
  diode_footprint: string
  switch_rotation: number
  diode: { x: number; y: number; rotation: number; side: BoardSide }
  footprints: { reference: string; layer: string; pads: GoldenPad[] }[]
}

const cases = golden.cases as GoldenCase[]
const FOOTPRINTS_DIR = resolve(__dirname, '../../../public/data/footprints')
// kbplacer rounds positions to integer nanometres
const TOLERANCE_MM = 1e-5
// kicad-cli writes SVG coordinates with 4 decimals, so a pad's outline (arcs as
// polylines) can be a step off centre
const SVG_TOLERANCE_MM = 2e-4

const mm = (p: { x_nm: number; y_nm: number }): Point => ({ x: p.x_nm / 1e6, y: p.y_nm / 1e6 })

function expectPoint(actual: Point, expected: Point, label: string, tolerance = TOLERANCE_MM) {
  expect(Math.abs(actual.x - expected.x), `${label} x: ${actual.x} vs ${expected.x}`).toBeLessThan(
    tolerance,
  )
  expect(Math.abs(actual.y - expected.y), `${label} y: ${actual.y} vs ${expected.y}`).toBeLessThan(
    tolerance,
  )
}

function caseName(c: GoldenCase): string {
  const d = c.diode
  return `${c.switch_footprint.split(':')[1]} at ${c.switch_rotation}°, diode ${d.x} ${d.y} ${d.rotation} ${d.side}`
}

function pads(c: GoldenCase, reference: string): GoldenPad[] {
  const footprint = c.footprints.find((f) => f.reference === reference)
  if (!footprint) throw new Error(`${reference} missing in ${caseName(c)}`)
  return footprint.pads
}

// Diode pads in the diode's own footprint frame: each footprint's identity placement case.
function diodeLocalOf(footprint: string): Map<string, Point> {
  const identity = cases.find(
    (c) =>
      c.diode_footprint === footprint &&
      c.diode.x === 0 &&
      c.diode.y === 0 &&
      c.diode.rotation === 0 &&
      c.diode.side === 'FRONT',
  )
  if (!identity) throw new Error(`no identity case for ${footprint}`)
  return new Map(pads(identity, 'D1').map((p) => [p.number, mm(p.switch_local)]))
}
const diodeLocal = diodeLocalOf('Diode_SMD:D_SOD-123F')
const diodeFootprints = [...new Set(cases.map((c) => c.diode_footprint))]
const svgName = (footprint: string) => footprint.split(':')[1]!
const diodeSvg = (side: string, footprint: string) =>
  readFileSync(resolve(FOOTPRINTS_DIR, side, `${svgName(footprint)}.svg`), 'utf-8')

/** Evaluates an SVG transform attribute (translate/rotate/scale) on a point. */
function applySvgTransform(transform: string, p: Point): Point {
  const ops = [...transform.matchAll(/(translate|rotate|scale)\(([^)]*)\)/g)]
  // SVG applies the rightmost transform first
  return ops.reverse().reduce((q, [, op, args]) => {
    const [a = 0, b] = args!.split(/[\s,]+/).map(Number)
    if (op === 'translate') return { x: q.x + a, y: q.y + (b ?? 0) }
    if (op === 'scale') return { x: q.x * a, y: q.y * (b ?? a) }
    const rad = (a * Math.PI) / 180
    return {
      x: q.x * Math.cos(rad) - q.y * Math.sin(rad),
      y: q.x * Math.sin(rad) + q.y * Math.cos(rad),
    }
  }, p)
}

/** Vertices of an SVG path made of straight lines (M, L, H, V, Z). */
function pathPoints(d: string): Point[] {
  const tokens = d.match(/[MmLlHhVvZz]|-?\d*\.?\d+(?:e-?\d+)?/g)!
  let x = 0
  let y = 0
  let command = ''
  const points: Point[] = []
  for (let i = 0; i < tokens.length;) {
    const token = tokens[i]!
    if (/[A-Za-z]/.test(token)) {
      command = token
      i++
      if (command === 'Z' || command === 'z') continue
    }
    const relative = command === command.toLowerCase()
    switch (command.toUpperCase()) {
      case 'M':
      case 'L':
        x = Number(tokens[i]) + (relative ? x : 0)
        y = Number(tokens[i + 1]) + (relative ? y : 0)
        i += 2
        // coordinates after a moveto are implicit linetos
        if (command === 'M') command = 'L'
        if (command === 'm') command = 'l'
        break
      case 'H':
        x = Number(tokens[i]) + (relative ? x : 0)
        i++
        break
      case 'V':
        y = Number(tokens[i]) + (relative ? y : 0)
        i++
        break
      default:
        throw new Error(`Unsupported path command ${command}`)
    }
    points.push({ x, y })
  }
  return points
}

/** Vertices of each path of a footprint SVG, pads (class="hoverable") or the rest. */
function svgPaths(svg: string, pads: boolean): Point[][] {
  return [...svg.matchAll(/<path\b([^>]*?)\sd="([^"]+)"/g)]
    .filter((m) => m[1]!.includes('class="hoverable"') === pads)
    .map((m) => pathPoints(m[2]!))
}

/** Bounding box centres of the pad paths of a footprint SVG, and its round pads' centres. */
function svgPadCentres(svg: string): Point[] {
  const paths = svgPaths(svg, true).map((points) => {
    const xs = points.map((p) => p.x)
    const ys = points.map((p) => p.y)
    return {
      x: (Math.min(...xs) + Math.max(...xs)) / 2,
      y: (Math.min(...ys) + Math.max(...ys)) / 2,
    }
  })
  const circles = [...svg.matchAll(/<circle\b[^>]*>/g)]
    .map((m) => m[0])
    .filter((tag) => tag.includes('class="hoverable"'))
    .map((tag) => ({
      x: Number(/\bcx="([^"]+)"/.exec(tag)![1]),
      y: Number(/\bcy="([^"]+)"/.exec(tag)![1]),
    }))
  return [...paths, ...circles]
}

describe('PCB preview coordinate contract (kbplacer golden pads)', () => {
  it('fixture comes from KiCad and covers rotations and both sides', () => {
    expect(golden.kicad_version).toMatch(/^\d+\./)
    const sides = new Set(cases.map((c) => c.diode.side))
    const rotations = new Set(cases.map((c) => c.diode.rotation))
    expect(sides).toEqual(new Set(['FRONT', 'BACK']))
    expect(rotations).toEqual(new Set([0, 90, 270]))
  })

  // the case the plan relies on: a wrong sign or mirror swaps K and A
  it('places SOD-123F K at (5.08, 5.4) and A at (5.08, 2.6) at the default 90 BACK', () => {
    expect.hasAssertions()
    const placement = { x: 5.08, y: 4, rotation: 90, side: 'BACK' as const }
    expectPoint(placePoint(diodeLocal.get('1')!, placement), { x: 5.08, y: 5.4 }, 'K')
    expectPoint(placePoint(diodeLocal.get('2')!, placement), { x: 5.08, y: 2.6 }, 'A')
  })

  it('covers a THT diode, whose origin is pin 1', () => {
    expect(diodeFootprints).toContain('Diode_THT:D_DO-35_SOD27_P7.62mm_Horizontal')
    const local = diodeLocalOf('Diode_THT:D_DO-35_SOD27_P7.62mm_Horizontal')
    expectPoint(local.get('1')!, { x: 0, y: 0 }, 'K')
    expectPoint(local.get('2')!, { x: 7.62, y: 0 }, 'A')
  })

  describe.each(cases.map((c) => [`${caseName(c)}, ${svgName(c.diode_footprint)}`, c] as const))(
    '%s',
    (_, c) => {
      const placement = { ...c.diode }
      const diodeLocal = diodeLocalOf(c.diode_footprint)

      it('maps diode pads to switch-local and board coordinates', () => {
        expect.hasAssertions()
        for (const pad of pads(c, 'D1')) {
          const local = placePoint(diodeLocal.get(pad.number)!, placement)
          expectPoint(local, mm(pad.switch_local), `D1 pad ${pad.number} local`)
          expectPoint(
            switchLocalToBoard(local, c.switch_rotation),
            mm(pad.board),
            `D1 pad ${pad.number} board`,
          )
        }
      })

      it('maps switch pads to board coordinates', () => {
        expect.hasAssertions()
        for (const pad of pads(c, 'SW1')) {
          expectPoint(
            switchLocalToBoard(mm(pad.switch_local), c.switch_rotation),
            mm(pad.board),
            `SW1 pad ${pad.number}`,
          )
        }
      })

      it('hover coordinates match kbplacer', () => {
        expect.hasAssertions()
        // the shipped diode SVG is centred on the footprint origin
        const vb = parseViewBox(diodeSvg(c.diode.side.toLowerCase(), c.diode_footprint))
        for (const pad of pads(c, 'D1')) {
          const local = diodeLocal.get(pad.number)!
          const world = applyDiodeTransform(
            local.x,
            local.y,
            vb,
            c.diode.x,
            c.diode.y,
            c.diode.rotation,
            c.switch_rotation,
            c.diode.side,
          )
          expectPoint(world, mm(pad.board), `D1 pad ${pad.number}`)
        }
        const switchVB = { x: -10, y: -10, width: 20, height: 20 }
        for (const pad of pads(c, 'SW1')) {
          const local = mm(pad.switch_local)
          const world = applySwitchTransform(local.x, local.y, switchVB, c.switch_rotation)
          expectPoint(world, mm(pad.board), `SW1 pad ${pad.number}`)
        }
      })
    },
  )
})

describe('Rendered footprint SVGs', () => {
  const svg = (side: string, name: string) =>
    readFileSync(resolve(FOOTPRINTS_DIR, side, `${name}.svg`), 'utf-8')

  it.each(diodeFootprints)('draws the %s SVG pads where kbplacer places them', (footprint) => {
    const diodeLocal = diodeLocalOf(footprint)
    const diodeSvg = svg('back', svgName(footprint))
    const vb = parseViewBox(diodeSvg)
    // SVG pads carry no numbers: number them by their footprint position, so
    // swapped pads (e.g. K and A) fail the comparison below
    const svgPads = new Map(
      svgPadCentres(diodeSvg).map((centre) => {
        const number = [...diodeLocal].find(
          ([, local]) => Math.hypot(local.x - centre.x, local.y - centre.y) < 1e-3,
        )?.[0]
        expect(number, `no footprint pad at SVG pad (${centre.x}, ${centre.y})`).toBeDefined()
        return [number!, centre] as const
      }),
    )
    expect(svgPads.size).toBe(diodeLocal.size)

    for (const c of cases.filter((c) => c.diode_footprint === footprint)) {
      const transform = offsetSvgTransform(
        {
          vb,
          offsetX: c.diode.x,
          offsetY: c.diode.y,
          rotation: c.diode.rotation,
          side: c.diode.side,
        },
        c.switch_rotation,
      )
      for (const pad of pads(c, 'D1')) {
        expectPoint(
          applySvgTransform(transform, svgPads.get(pad.number)!),
          mm(pad.board),
          `${caseName(c)} D1 pad ${pad.number}`,
          SVG_TOLERANCE_MM,
        )
      }
    }
  })

  it('renders and hovers an asymmetric point the same way as the contract functions', () => {
    expect.hasAssertions()
    // SOD-123F pads are symmetric, so check mirroring and rotation direction on
    // an arbitrary point too
    const vb = { x: -3, y: -1, width: 6, height: 2 }
    const p = { x: 0.7, y: -0.3 }
    for (const side of ['FRONT', 'BACK'] as const) {
      for (const [rotation, switchRotation] of [
        [90, 0],
        [270, 37],
        [0, 90],
      ] as const) {
        const placement = { x: 5.08, y: 4, rotation, side }
        const expected = switchLocalToBoard(placePoint(p, placement), switchRotation)
        const transform = offsetSvgTransform(
          { vb, offsetX: 5.08, offsetY: 4, rotation, side },
          switchRotation,
        )
        expectPoint(
          applySvgTransform(transform, p),
          expected,
          `${side} ${rotation}/${switchRotation}`,
        )
        expectPoint(
          applyDiodeTransform(p.x, p.y, vb, 5.08, 4, rotation, switchRotation, side),
          expected,
          `hover ${side} ${rotation}/${switchRotation}`,
        )
        expectPoint(
          applySvgTransform(switchSvgTransform(vb, switchRotation, side), p),
          applySwitchTransform(p.x, p.y, vb, switchRotation, side),
          `switch ${side} ${switchRotation}`,
        )
      }
    }
  })

  // The track preset overlay draws switch-local tracks. The kle-ng default preset
  // runs from SW pad 2 to D pad 2 (A) at the default diode placement.
  it('draws the default track preset from SW pad 2 to D pad 2 (A)', () => {
    expect.hasAssertions()
    const presetStart = { x: 2.54, y: -5.08 }
    const presetEnd = { x: 5.08, y: 2.6 }
    const defaults = cases.filter(
      (c) =>
        c.switch_footprint.startsWith('Switch_Keyboard_Cherry_MX:') &&
        c.diode.x === 5.08 &&
        c.diode.y === 4 &&
        c.diode.rotation === 90 &&
        c.diode.side === 'BACK',
    )
    expect(defaults.map((c) => c.switch_rotation).sort()).toEqual([0, 37, 90])
    for (const c of defaults) {
      const transform = switchLocalSvgTransform(c.switch_rotation)
      const swPad2 = pads(c, 'SW1').find((p) => p.number === '2')!
      const dPad2 = pads(c, 'D1').find((p) => p.number === '2')!
      expectPoint(
        applySvgTransform(transform, presetStart),
        mm(swPad2.board),
        `${caseName(c)} start`,
      )
      expectPoint(applySvgTransform(transform, presetEnd), mm(dPad2.board), `${caseName(c)} end`)
    }
  })

  // SVGs are drawn as seen from the front, the preview mirrors BACK footprints
  // itself. Symmetric pads can't show a mirrored drawing, the F.Fab lines can.
  it.each(
    Object.keys(golden.fab_segments).flatMap((name) =>
      ['front', 'back'].map((side) => [`${side}/${name}.svg`, side, name] as const),
    ),
  )('%s draws the KiCad F.Fab lines unmirrored', (_, side, name) => {
    const drawn = svgPaths(svg(side, name), false).flatMap((points) =>
      points.slice(1).map((end, i) => [points[i]!, end] as const),
    )
    const same = (a: Point, b: Point) => Math.hypot(a.x - b.x, a.y - b.y) < 1e-3
    const segments = golden.fab_segments[name as keyof typeof golden.fab_segments]
    expect(segments.length).toBeGreaterThan(0)
    for (const segment of segments) {
      const start = mm(segment[0]!)
      const end = mm(segment[1]!)
      const found = drawn.some(
        ([a, b]) => (same(a, start) && same(b, end)) || (same(a, end) && same(b, start)),
      )
      expect(found, `F.Fab line (${start.x}, ${start.y}) - (${end.x}, ${end.y})`).toBe(true)
    }
  })

  // Preview centres switch and diode SVGs on their viewBox, which is only the
  // footprint origin when the export kept footprint coordinates
  it.each(
    ['front', 'back'].flatMap((side) =>
      readdirSync(resolve(FOOTPRINTS_DIR, side))
        .filter((f) => /^(SW|D)_.*\.svg$/.test(f))
        .map((f) => [`${side}/${f}`, side, f.replace(/\.svg$/, '')] as const),
    ),
  )('%s has its viewBox centred on the footprint origin', (_, side, name) => {
    const vb = parseViewBox(svg(side, name))
    expect(Math.abs(vb.x + vb.width / 2)).toBeLessThan(1e-3)
    expect(Math.abs(vb.y + vb.height / 2)).toBeLessThan(1e-3)
  })
})
